CREATE FUNCTION public.validate_reservation_config() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE c jsonb:=NEW.config; k text; v jsonb; w jsonb; r jsonb; BEGIN IF jsonb_typeof(c) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Booking settings are incomplete.'; END IF; FOREACH k IN ARRAY ARRAY['enabled','approval_required','use_upper'] LOOP IF jsonb_typeof(c->k) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Booking settings are incomplete.'; END IF; END LOOP; FOREACH k IN ARRAY ARRAY['before_minutes','after_minutes','step_minutes','advance_days','lead_minutes'] LOOP IF jsonb_typeof(c->k) IS DISTINCT FROM 'number' OR (c->>k)!~'^[0-9]+$' THEN RAISE EXCEPTION 'Booking rules require whole numbers.'; END IF; END LOOP; IF (c->>'before_minutes')::integer NOT BETWEEN 0 AND 120 OR (c->>'after_minutes')::integer NOT BETWEEN 0 AND 120 OR (c->>'step_minutes')::integer NOT BETWEEN 5 AND 120 OR (c->>'advance_days')::integer NOT BETWEEN 1 AND 730 OR (c->>'lead_minutes')::integer NOT BETWEEN 0 AND 10080 THEN RAISE EXCEPTION 'Booking rules are outside the allowed range.'; END IF; IF jsonb_typeof(c->'games') IS DISTINCT FROM 'array' OR jsonb_typeof(c->'estimates') IS DISTINCT FROM 'array' OR jsonb_typeof(c->'weekly') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Booking settings are incomplete.'; END IF; IF jsonb_array_length(c->'games') NOT BETWEEN 1 AND 20 OR jsonb_array_length(c->'estimates')<>6 OR jsonb_array_length(c->'weekly')<>7 THEN RAISE EXCEPTION 'Choose valid games, six estimates and seven days.'; END IF; FOR v IN SELECT value FROM jsonb_array_elements(c->'games') LOOP IF jsonb_typeof(v) IS DISTINCT FROM 'number' OR v::text!~'^[0-9]+$' OR v::text::integer NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Choose valid games.'; END IF; END LOOP; FOR r IN SELECT value FROM jsonb_array_elements(c->'estimates') LOOP IF jsonb_typeof(r) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid duration estimates.'; END IF; IF jsonb_array_length(r)<>2 OR coalesce(r->>0,'')!~'^[0-9]+$' OR coalesce(r->>1,'')!~'^[0-9]+$' THEN RAISE EXCEPTION 'Invalid duration estimates.'; END IF; IF (r->>0)::integer NOT BETWEEN 1 AND 240 OR (r->>1)::integer NOT BETWEEN (r->>0)::integer AND 240 THEN RAISE EXCEPTION 'Invalid duration estimates.'; END IF; END LOOP; FOR w IN SELECT value FROM jsonb_array_elements(c->'weekly') LOOP IF jsonb_typeof(w) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid bookable hours.'; END IF; FOR r IN SELECT value FROM jsonb_array_elements(w) LOOP IF jsonb_typeof(r) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid bookable hours.'; END IF; IF jsonb_array_length(r)<>2 OR coalesce(r->>0,'')!~'^[0-9]+$' OR coalesce(r->>1,'')!~'^[0-9]+$' THEN RAISE EXCEPTION 'Invalid bookable hours.'; END IF; IF (r->>0)::integer NOT BETWEEN 0 AND 1439 OR (r->>1)::integer NOT BETWEEN (r->>0)::integer+1 AND 1440 THEN RAISE EXCEPTION 'Invalid bookable hours.'; END IF; END LOOP; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER reservation_config_guard BEFORE INSERT OR UPDATE ON public.reservation_settings FOR EACH ROW EXECUTE FUNCTION public.validate_reservation_config();
CREATE OR REPLACE FUNCTION public.reservation_duration(p_alloc integer[],p_games integer) RETURNS integer LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;n integer;highest integer:=0;v integer; BEGIN SELECT config INTO c FROM reservation_settings WHERE id=1; IF c IS NULL OR coalesce(cardinality(p_alloc),0) NOT BETWEEN 1 AND 6 OR p_games IS NULL OR NOT coalesce(c->'games' @> to_jsonb(ARRAY[p_games]),false) THEN RAISE EXCEPTION 'Choose 1–6 lanes and an available number of games.'; END IF; FOREACH n IN ARRAY p_alloc LOOP IF n IS NULL OR n NOT BETWEEN 1 AND 6 THEN RAISE EXCEPTION 'Each lane must have 1–6 bowlers.'; END IF; v:=(c->'estimates'->(n-1)->>(CASE WHEN coalesce((c->>'use_upper')::boolean,true) THEN 1 ELSE 0 END))::integer*p_games; IF v IS NULL THEN RAISE EXCEPTION 'Booking settings are incomplete.'; END IF; highest:=greatest(highest,v); END LOOP; RETURN highest; END $$;
REVOKE INSERT,UPDATE,DELETE,TRUNCATE ON public.reservation_settings,public.lane_reservations,public.lane_occupancy,public.lane_schedule_blocks,public.reservation_date_hours,public.reservation_audit FROM anon,authenticated;
ALTER TABLE public.lane_reservations ADD CONSTRAINT valid_lane_allocations CHECK(cardinality(allocations) BETWEEN 1 AND 6 AND cardinality(lanes)=cardinality(allocations) AND allocations<@ARRAY[1,2,3,4,5,6] AND lanes<@ARRAY[1,2,3,4,5,6] AND array_position(allocations,NULL) IS NULL AND array_position(lanes,NULL) IS NULL AND duration_minutes BETWEEN 1 AND 1440 AND before_minutes BETWEEN 0 AND 120 AND after_minutes BETWEEN 0 AND 120) NOT VALID;
ALTER TABLE public.lane_schedule_blocks ADD CONSTRAINT valid_block_lanes CHECK(cardinality(lanes) BETWEEN 1 AND 6 AND lanes<@ARRAY[1,2,3,4,5,6] AND array_position(lanes,NULL) IS NULL) NOT VALID;
ALTER TABLE public.lane_occupancy ADD CONSTRAINT nonempty_occupied CHECK(NOT isempty(occupied)) NOT VALID;